{"sql":"SELECT ss.AvgScrMath AS average_math_score, ss.cname AS county_name
FROM satscores ss
WHERE (COALESCE(ss.AvgScrRead,0) + COALESCE(ss.AvgScrMath,0) + COALESCE(ss.AvgScrWrite,0)) = (
  SELECT MIN(COALESCE(AvgScrRead,0) + COALESCE(AvgScrMath,0) + COALESCE(AvgScrWrite,0))
  FROM satscores
)"}
